use super::types::{FunctionCall, ToolCall};
use regex::Regex;
use serde_json::Value;

/// Robust tool call extractor that parses structured tool invocations from text
/// outputs generated by open-source models (DeepSeek DSML, GLM markup, JSON blocks, XML).
pub struct ToolCallExtractor;

impl ToolCallExtractor {
    /// Attempt to extract tool calls from model text output
    pub fn extract(text: &str) -> Option<Vec<ToolCall>> {
        let mut calls = Vec::new();

        // 1. DeepSeek DSML format: <｜DSML｜invoke name="NAME">...<｜DSML｜parameter name="PARAM">VAL</｜DSML｜parameter>...</｜DSML｜invoke>
        if let Some(dsml_calls) = Self::extract_dsml(text) {
            calls.extend(dsml_calls);
        }

        // 2. GLM markup & generic <tool_call>...</tool_call>
        if calls.is_empty() {
            if let Some(glm_calls) = Self::extract_glm_or_xml(text) {
                calls.extend(glm_calls);
            }
        }

        // 3. Markdown JSON block: ```json\n{"name": "...", "arguments": {...}}\n```
        if calls.is_empty() {
            if let Some(json_calls) = Self::extract_json_blocks(text) {
                calls.extend(json_calls);
            }
        }

        if !calls.is_empty() {
            Some(calls)
        } else {
            None
        }
    }

    /// Extract DeepSeek DSML tool calls
    fn extract_dsml(text: &str) -> Option<Vec<ToolCall>> {
        let dsml_invoke_re = Regex::new(r"(?s)<[｜|]DSML[｜|]invoke\s+name=[\x22']([^'\x22]+)[\x22']\s*>(.*?)</[｜|]DSML[｜|]invoke>").ok()?;
        let dsml_param_re = Regex::new(r"(?s)<[｜|]DSML[｜|]parameter\s+name=[\x22']([^'\x22]+)[\x22'][^>]*>(.*?)</[｜|]DSML[｜|]parameter>").ok()?;

        let mut calls = Vec::new();
        let mut idx = 0;

        for cap in dsml_invoke_re.captures_iter(text) {
            let name = cap.get(1).map(|m| m.as_str().trim()).unwrap_or("");
            let body = cap.get(2).map(|m| m.as_str()).unwrap_or("");
            if !name.is_empty() {
                let mut map = serde_json::Map::new();
                for pcap in dsml_param_re.captures_iter(body) {
                    let pname = pcap.get(1).map(|m| m.as_str().trim()).unwrap_or("");
                    let pval = pcap.get(2).map(|m| m.as_str().trim()).unwrap_or("");
                    if !pname.is_empty() {
                        map.insert(pname.to_string(), Value::String(pval.to_string()));
                    }
                }
                calls.push(ToolCall {
                    id: format!("call_dsml_{idx}"),
                    tool_type: "function".to_string(),
                    function: FunctionCall {
                        name: name.to_string(),
                        arguments: serde_json::to_string(&map).unwrap_or_else(|_| "{}".to_string()),
                    },
                });
                idx += 1;
            }
        }

        if !calls.is_empty() {
            Some(calls)
        } else {
            None
        }
    }

    /// Extract GLM and XML tool calls enclosed in <tool_call> tags
    fn extract_glm_or_xml(text: &str) -> Option<Vec<ToolCall>> {
        let tool_call_re = Regex::new(r"(?s)<tool_call>(.*?)</tool_call>").ok()?;
        let mut calls = Vec::new();
        let mut idx = 0;

        for cap in tool_call_re.captures_iter(text) {
            let body = cap.get(1).map(|m| m.as_str().trim()).unwrap_or("");
            if body.is_empty() {
                continue;
            }

            // A. If body is valid JSON: {"name": "...", "arguments": {...}}
            if body.starts_with('{') {
                if let Ok(v) = serde_json::from_str::<Value>(body) {
                    let name = v.get("name").or_else(|| v.get("tool")).and_then(|n| n.as_str()).unwrap_or("");
                    let args = if let Some(a) = v.get("arguments").or_else(|| v.get("parameters")) {
                        if a.is_string() {
                            a.as_str().unwrap().to_string()
                        } else {
                            serde_json::to_string(a).unwrap_or_else(|_| "{}".to_string())
                        }
                    } else {
                        "{}".to_string()
                    };

                    if !name.is_empty() {
                        calls.push(ToolCall {
                            id: format!("call_glm_json_{idx}"),
                            tool_type: "function".to_string(),
                            function: FunctionCall {
                                name: name.to_string(),
                                arguments: args,
                            },
                        });
                        idx += 1;
                        continue;
                    }
                }
            }

            // B. GLM custom markup: write_file<arg_value>path</arg_key><arg_value>src/config_loader.py\ncontent</arg_key><arg_value>...
            let parts: Vec<&str> = body.splitn(2, "<arg_value>").collect();
            let name = parts[0].trim();
            if !name.is_empty() && parts.len() > 1 {
                let rest = parts[1];
                let segments: Vec<&str> = rest.split("</arg_key><arg_value>").collect();
                let mut map = serde_json::Map::new();
                if segments.len() > 1 {
                    let mut cur_key = segments[0].trim();
                    for (s_idx, seg) in segments.iter().enumerate().skip(1) {
                        if s_idx == segments.len() - 1 {
                            // Last segment: strip trailing </arg_value>
                            let val = if let Some(stripped) = seg.strip_suffix("</arg_value>") {
                                stripped.trim()
                            } else {
                                seg.trim()
                            };
                            map.insert(cur_key.to_string(), Value::String(val.to_string()));
                        } else {
                            // Intermediate segment: value ending with newline and next_key
                            if let Some((val, next_key)) = seg.rsplit_once('\n') {
                                map.insert(cur_key.to_string(), Value::String(val.trim().to_string()));
                                cur_key = next_key.trim();
                            } else {
                                map.insert(cur_key.to_string(), Value::String(seg.trim().to_string()));
                            }
                        }
                    }
                }

                calls.push(ToolCall {
                    id: format!("call_glm_markup_{idx}"),
                    tool_type: "function".to_string(),
                    function: FunctionCall {
                        name: name.to_string(),
                        arguments: serde_json::to_string(&map).unwrap_or_else(|_| "{}".to_string()),
                    },
                });
                idx += 1;
            }
        }

        if !calls.is_empty() {
            Some(calls)
        } else {
            None
        }
    }

    /// Extract tool calls from Markdown JSON code blocks
    fn extract_json_blocks(text: &str) -> Option<Vec<ToolCall>> {
        let code_block_re = Regex::new(r"(?s)```(?:json)?\s*(\{.*?\})\s*```").ok()?;
        let mut calls = Vec::new();
        let mut idx = 0;

        for cap in code_block_re.captures_iter(text) {
            let json_str = cap.get(1).map(|m| m.as_str().trim()).unwrap_or("");
            if let Ok(v) = serde_json::from_str::<Value>(json_str) {
                let name = v.get("name").or_else(|| v.get("tool")).and_then(|n| n.as_str()).unwrap_or("");
                let args = if let Some(a) = v.get("arguments").or_else(|| v.get("parameters")) {
                    if a.is_string() {
                        a.as_str().unwrap().to_string()
                    } else {
                        serde_json::to_string(a).unwrap_or_else(|_| "{}".to_string())
                    }
                } else {
                    "{}".to_string()
                };

                if !name.is_empty() {
                    calls.push(ToolCall {
                        id: format!("call_json_block_{idx}"),
                        tool_type: "function".to_string(),
                        function: FunctionCall {
                            name: name.to_string(),
                            arguments: args,
                        },
                    });
                    idx += 1;
                }
            }
        }

        if !calls.is_empty() {
            Some(calls)
        } else {
            None
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_extract_dsml_tool_calls() {
        let text = r#"Let me check the config:
<｜DSML｜tool_calls>
<｜DSML｜invoke name="read_file">
<｜DSML｜parameter name="path" string="true">app/config.yaml</｜DSML｜parameter>
</｜DSML｜invoke>
</｜DSML｜tool_calls>"#;

        let calls = ToolCallExtractor::extract(text).expect("Should extract DSML tool calls");
        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].function.name, "read_file");
        assert!(calls[0].function.arguments.contains("app/config.yaml"));
    }

    #[test]
    fn test_extract_glm_tool_calls() {
        let text = r#"Refactoring config:
<tool_call>write_file<arg_value>path</arg_key><arg_value>src/config_loader.py
content</arg_key><arg_value>import json
def load_config(): pass</arg_value></tool_call>"#;

        let calls = ToolCallExtractor::extract(text).expect("Should extract GLM tool calls");
        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].function.name, "write_file");
        assert!(calls[0].function.arguments.contains("src/config_loader.py"));
        assert!(calls[0].function.arguments.contains("load_config"));
    }

    #[test]
    fn test_extract_markdown_json_block() {
        let text = r#"Here is the action:
```json
{
  "name": "bash",
  "arguments": {
    "command": "cargo test"
  }
}
```"#;

        let calls = ToolCallExtractor::extract(text).expect("Should extract JSON code block");
        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].function.name, "bash");
        assert!(calls[0].function.arguments.contains("cargo test"));
    }
}
